-- Reviewed senior batch 013; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":3831,"word":"rebellion","meaning":"叛亂","example":"The exhibit traced the causes of a rebellion against the unfair ruler.","example_zh":"展覽追溯反抗不公統治者的叛亂起因。","original_meaning":"叛亂","original_example":"The rebellion was quickly suppressed.","original_example_zh":"叛亂很快被鎮壓。"},{"source_id":3832,"word":"recitation","meaning":"朗誦","example":"Her recitation of the poem held the audience's attention.","example_zh":"她的詩歌朗誦吸引全場注意。","original_meaning":"朗誦","original_example":"She practiced recitation daily.","original_example_zh":"她每天練習背誦。"},{"source_id":3833,"word":"reconnaissance","meaning":"偵察","example":"The rescue team used a drone for reconnaissance after the flood.","example_zh":"洪水過後，救援隊用無人機偵察環境。","original_meaning":"偵察","original_example":"The army conducted reconnaissance missions.","original_example_zh":"軍隊執行了偵察任務。"},{"source_id":3834,"word":"reconstruction","meaning":"重建","example":"The reconstruction of the old bridge brought the villages together.","example_zh":"重建老橋讓兩個村莊重新連結。","original_meaning":"重建","original_example":"The city underwent reconstruction.","original_example_zh":"這座城市進行了重建。"},{"source_id":3835,"word":"referendum","meaning":"公投","example":"The town held a referendum on the proposed public park.","example_zh":"城鎮就公共公園提案舉行公投。","original_meaning":"公投","original_example":"The referendum determined the outcome.","original_example_zh":"公投決定了結果。"},{"source_id":3836,"word":"reformer","meaning":"改革者","example":"The educational reformer argued for more accessible schools.","example_zh":"教育改革者主張讓學校更方便所有人就讀。","original_meaning":"改革者","original_example":"The reformer changed the system.","original_example_zh":"改革者改變了體制。"},{"source_id":3837,"word":"rehabilitation","meaning":"復健","example":"The therapist guided his rehabilitation after the knee injury.","example_zh":"膝蓋受傷後，治療師指導他進行復健。","original_meaning":"復健","original_example":"The patient began rehabilitation.","original_example_zh":"病患開始進行復健。"},{"source_id":3838,"word":"reiterate","meaning":"重申","example":"The coach will reiterate the safety rules before every practice.","example_zh":"每次練習前，教練都會重申安全規則。","original_meaning":"重申","original_example":"He reiterated his point clearly.","original_example_zh":"他清楚地重申了自己的觀點。"},{"source_id":3839,"word":"reliance","meaning":"依賴","example":"The school reduced its reliance on bottled water by adding refill stations.","example_zh":"學校增設飲水補充站，減少對瓶裝水的依賴。","original_meaning":"依賴","original_example":"She showed reliance on her team.","original_example_zh":"她展現出對團隊的信賴。"},{"source_id":3840,"word":"remnant","meaning":"殘餘","example":"A remnant of the old wall stood beside the new garden.","example_zh":"新花園旁仍矗立一小段舊牆殘跡。","original_meaning":"殘餘","original_example":"Only a remnant of the building remains.","original_example_zh":"這棟建築只剩殘骸。"},{"source_id":3841,"word":"remuneration","meaning":"報酬","example":"The musicians received fair remuneration for their performance.","example_zh":"音樂家為演出獲得合理報酬。","original_meaning":"報酬","original_example":"The job offers good remuneration.","original_example_zh":"這份工作報酬優渥。"},{"source_id":3842,"word":"rendition","meaning":"演繹","example":"The ensemble gave a lively rendition of the old folk tune.","example_zh":"合奏團生動演繹那首古老民謠。","original_meaning":"演繹","original_example":"The song is a beautiful rendition.","original_example_zh":"這首歌的演繹非常動聽。"},{"source_id":3843,"word":"renovation","meaning":"翻新","example":"The renovation gave the library brighter study rooms.","example_zh":"翻新工程讓圖書館有了更明亮的自習室。","original_meaning":"翻新","original_example":"The house is under renovation.","original_example_zh":"房子正在翻新中。"},{"source_id":3844,"word":"reparation","meaning":"賠償","example":"The agreement included reparation for the damage to the shared garden.","example_zh":"協議包含對公共花園損壞的賠償。","original_meaning":"賠償","original_example":"The victims demanded reparation.","original_example_zh":"受害者要求賠償。"},{"source_id":3845,"word":"repercussion","meaning":"影響","example":"The road closure had an unexpected repercussion for the village market.","example_zh":"道路封閉對村莊市集造成意外影響。","original_meaning":"影響","original_example":"His actions had serious repercussions.","original_example_zh":"他的行為引發了嚴重後果。"},{"source_id":3846,"word":"repository","meaning":"儲存庫","example":"The archive became a repository for the town's historic photographs.","example_zh":"檔案館成為保存城鎮歷史照片的資料庫。","original_meaning":"儲存庫","original_example":"The code is stored in a repository.","original_example_zh":"程式碼儲存於儲存庫中。"},{"source_id":3847,"word":"repression","meaning":"壓迫","example":"The exhibit examined the repression of peaceful dissent.","example_zh":"展覽探討對和平異議的壓制。","original_meaning":"壓迫","original_example":"The government enforced repression.","original_example_zh":"政府實施了鎮壓。"},{"source_id":3848,"word":"reproduction","meaning":"繁殖","example":"The biology lesson explored reproduction in flowering plants.","example_zh":"生物課探討開花植物的繁殖。","original_meaning":"繁殖","original_example":"Reproduction is essential for survival.","original_example_zh":"繁殖對生存至關重要。"},{"source_id":3849,"word":"republic","meaning":"共和國","example":"The class studied how citizens elect representatives in a republic.","example_zh":"班上研究共和國中的公民如何選出代表。","original_meaning":"共和國","original_example":"The country became a republic.","original_example_zh":"該國成為共和國。"},{"source_id":3850,"word":"requisite","meaning":"必要的","example":"The team gathered the requisite tools before repairing the benches.","example_zh":"團隊修理長椅前先備齊必要工具。","original_meaning":"必要的","original_example":"This is a requisite condition.","original_example_zh":"這是必要條件。"},{"source_id":3851,"word":"resemblance","meaning":"相似","example":"The resemblance between the leaf and the insect was remarkable.","example_zh":"那片葉子與昆蟲的相似程度令人驚訝。","original_meaning":"相似","original_example":"There is a strong resemblance between them.","original_example_zh":"他們之間有很強的相似性。"},{"source_id":3852,"word":"resentment","meaning":"怨恨","example":"Her resentment faded after the group apologized for leaving her out.","example_zh":"小組為漏邀她道歉後，她的怨懟逐漸消退。","original_meaning":"怨恨","original_example":"He felt deep resentment.","original_example_zh":"他感到深深的怨恨。"},{"source_id":3853,"word":"residue","meaning":"殘留物","example":"A chalky residue remained in the cup after the water evaporated.","example_zh":"水蒸發後，杯中留下白堊狀殘留物。","original_meaning":"殘留物","original_example":"The lab tested chemical residue.","original_example_zh":"實驗室檢測了化學殘留物。"},{"source_id":3854,"word":"resilience","meaning":"韌性","example":"The community showed resilience by rebuilding the garden after the storm.","example_zh":"社區在風暴後重建花園，展現韌性。","original_meaning":"韌性","original_example":"She showed great resilience.","original_example_zh":"她展現了極大的韌性。"},{"source_id":3855,"word":"resolution","meaning":"決議","example":"The council passed a resolution to protect the old trees.","example_zh":"議會通過保護老樹的決議。","original_meaning":"決議","original_example":"The council passed a resolution.","original_example_zh":"議會通過了一項決議。"},{"source_id":3856,"word":"resonance","meaning":"共鳴","example":"The guitar's wooden body strengthened the resonance of its strings.","example_zh":"吉他的木製琴身增強琴弦的共鳴。","original_meaning":"共鳴","original_example":"The sound created a strong resonance.","original_example_zh":"聲音產生了強烈的共鳴。"},{"source_id":3857,"word":"restitution","meaning":"歸還","example":"The museum arranged the restitution of the artifact to its original community.","example_zh":"博物館安排把文物歸還原屬社群。","original_meaning":"歸還","original_example":"They demanded restitution.","original_example_zh":"他們要求賠償。"},{"source_id":3858,"word":"restructure","meaning":"重組","example":"The club will restructure its teams so that tasks are shared more fairly.","example_zh":"社團將重組小隊，讓工作分配更公平。","original_meaning":"重組","original_example":"The company plans to restructure.","original_example_zh":"該公司計劃進行重組。"},{"source_id":3859,"word":"resurrection","meaning":"復活","example":"The church painting portrayed the resurrection of Jesus.","example_zh":"教堂畫作描繪耶穌復活。","original_meaning":"復活","original_example":"The story talks about resurrection.","original_example_zh":"這個故事講述了復活。"},{"source_id":3860,"word":"retaliation","meaning":"報復","example":"The captain urged the team to seek discussion instead of retaliation.","example_zh":"隊長勸隊員尋求對話，避免報復。","original_meaning":"報復","original_example":"They feared retaliation.","original_example_zh":"他們擔心遭到報復。"},{"source_id":3861,"word":"retribution","meaning":"報應","example":"In the fable, the dishonest merchant faced retribution when customers stopped trusting him.","example_zh":"寓言中，不誠實的商人遭到報應，顧客不再信任他。","original_meaning":"報應","original_example":"Justice demands retribution.","original_example_zh":"正義要求報應。"},{"source_id":3862,"word":"retrospect","meaning":"回顧","example":"In retrospect, repairing the bridge was our most useful project.","example_zh":"回顧過往，修橋是我們最有用的專案。","original_meaning":"回顧","original_example":"In retrospect, it was a mistake.","original_example_zh":"事後看來，那是一個錯誤。"},{"source_id":3863,"word":"revelation","meaning":"啟示","example":"The hidden sketch was a revelation about the artist's original plan.","example_zh":"隱藏的草圖揭露藝術家最初的構想。","original_meaning":"啟示","original_example":"The discovery was a revelation.","original_example_zh":"這項發現令人大開眼界。"},{"source_id":3864,"word":"rigor","meaning":"嚴謹","example":"The students checked every measurement with scientific rigor.","example_zh":"學生以科學嚴謹態度核對每項測量。","original_meaning":"嚴謹","original_example":"The research requires academic rigor.","original_example_zh":"這項研究需要學術上的嚴謹性。"},{"source_id":3865,"word":"rivalry","meaning":"競爭","example":"The friendly rivalry between the clubs encouraged better bridge designs.","example_zh":"兩個社團的良性競爭促使橋梁設計進步。","original_meaning":"競爭","original_example":"There is strong rivalry between the teams.","original_example_zh":"兩支隊伍之間競爭激烈。"},{"source_id":3866,"word":"sabotage","meaning":"破壞","example":"The broken model led the teacher to investigate possible sabotage.","example_zh":"模型損壞，使老師開始調查是否有人蓄意破壞。","original_meaning":"破壞","original_example":"The act was considered sabotage.","original_example_zh":"該行為被視為破壞活動。"},{"source_id":3867,"word":"sacrament","meaning":"聖禮","example":"The museum explained the significance of the sacrament in Christian worship.","example_zh":"博物館解說聖禮在基督宗教禮拜中的意義。","original_meaning":"聖禮","original_example":"The ceremony included a sacrament.","original_example_zh":"儀式包含聖禮。"},{"source_id":3868,"word":"safeguard","meaning":"保護","example":"The sturdy case will safeguard the delicate violin during travel.","example_zh":"堅固琴盒會在旅途中保護精細的小提琴。","original_meaning":"保護","original_example":"The law safeguards citizens.","original_example_zh":"法律保障公民權益。"},{"source_id":3869,"word":"sanitary","meaning":"衛生的","example":"The kitchen staff kept the preparation area clean and sanitary.","example_zh":"廚房人員讓備餐區保持乾淨衛生。","original_meaning":"衛生的","original_example":"Clean water is essential for sanitary conditions.","original_example_zh":"潔淨的水對衛生條件至關重要。"},{"source_id":3870,"word":"satire","meaning":"諷刺","example":"The play used satire to criticize the mayor's obsession with grand ceremonies.","example_zh":"戲劇以諷刺手法批評市長對盛大典禮的迷戀。","original_meaning":"諷刺","original_example":"The film is a satire of politics.","original_example_zh":"這部電影是一部政治諷刺片。"},{"source_id":3871,"word":"scaffold","meaning":"腳手架","example":"The workers inspected the scaffold before restoring the church wall.","example_zh":"工人修復教堂牆面前先檢查腳手架。","original_meaning":"腳手架","original_example":"Workers stood on the scaffold.","original_example_zh":"工人站在腳手架上。"},{"source_id":3872,"word":"scenario","meaning":"情境","example":"We practiced a scenario in which heavy rain interrupted the school trip.","example_zh":"我們演練大雨打斷校外教學的情境。","original_meaning":"情境","original_example":"Imagine a scenario where this happens.","original_example_zh":"想像這種情況發生的場景。"},{"source_id":3873,"word":"schism","meaning":"分裂","example":"The disagreement caused a schism within the organization.","example_zh":"意見分歧造成組織內部分裂。","original_meaning":"分裂","original_example":"The conflict caused a religious schism.","original_example_zh":"這場衝突引發了宗教分裂。"},{"source_id":3874,"word":"scholarship","meaning":"獎學金","example":"The scholarship allowed her to continue studying music.","example_zh":"獎學金讓她能繼續學習音樂。","original_meaning":"獎學金","original_example":"My cousin used her scholarship to buy textbooks and a secondhand laptop.","original_example_zh":"表姊用獎學金買課本和一台二手筆電。"},{"source_id":3875,"word":"scrutinize","meaning":"審視","example":"The curator will scrutinize the signature before accepting the painting.","example_zh":"策展人會先仔細審視簽名，再決定是否接受畫作。","original_meaning":"審視","original_example":"The auditor scrutinized the accounts.","original_example_zh":"審計員仔細審查了帳目。"},{"source_id":3876,"word":"secession","meaning":"脫離；分離獨立","example":"The history lesson examined the region's secession from the larger state.","example_zh":"歷史課探討該地區脫離較大國家的過程。","original_meaning":"分裂","original_example":"The state threatened secession.","original_example_zh":"該州威脅要脫離聯邦。"},{"source_id":3877,"word":"secular","meaning":"世俗的；非宗教的","example":"The secular ceremony welcomed people of every religion.","example_zh":"這場非宗教儀式歡迎不同信仰的人參加。","original_meaning":"世俗的","original_example":"The school follows a secular system.","original_example_zh":"該校採用世俗教育體系。"},{"source_id":3878,"word":"sediment","meaning":"沉積物","example":"A layer of sediment settled at the bottom of the jar.","example_zh":"罐底沉積了一層沉積物。","original_meaning":"沉積物","original_example":"Sediment accumulated at the bottom.","original_example_zh":"沉積物積聚在底部。"},{"source_id":3879,"word":"segregate","meaning":"分隔；隔離","example":"The laboratory used separate cabinets to segregate different types of samples.","example_zh":"實驗室用不同櫃子分隔不同類型的樣本。","original_meaning":"隔離","original_example":"The law segregated communities.","original_example_zh":"法律將社區分隔開來。"},{"source_id":3880,"word":"seismology","meaning":"地震學","example":"The seismology exhibit showed how instruments record ground movement.","example_zh":"地震學展覽展示儀器如何記錄地面運動。","original_meaning":"地震學","original_example":"He studies seismology.","original_example_zh":"他研究地震學。"},{"source_id":3881,"word":"semiconductor","meaning":"半導體","example":"The engineer showed us a semiconductor used in an electronic circuit.","example_zh":"工程師向我們展示電子電路裡使用的半導體。","original_meaning":"半導體","original_example":"Semiconductors power modern devices.","original_example_zh":"半導體驅動現代裝置。"},{"source_id":3882,"word":"seminary","meaning":"神學院","example":"The visitors toured the seminary's historic library.","example_zh":"訪客參觀神學院的歷史圖書館。","original_meaning":"神學院","original_example":"He enrolled in a seminary.","original_example_zh":"他進入神學院就讀。"},{"source_id":3883,"word":"sentiment","meaning":"情感","example":"Her speech expressed a deep sentiment of gratitude.","example_zh":"她的演說表達深刻的感謝之情。","original_meaning":"情感","original_example":"Public sentiment was negative.","original_example_zh":"公眾輿論負面。"},{"source_id":3884,"word":"sequestration","meaning":"隔離","example":"The jurors' sequestration kept them apart from outside discussion during the trial.","example_zh":"陪審員在審判期間被隔離，避免接觸外界討論。","original_meaning":"隔離","original_example":"Carbon sequestration reduces emissions.","original_example_zh":"碳封存可減少排放。"},{"source_id":3885,"word":"serenity","meaning":"寧靜","example":"The lakeside garden offered a welcome sense of serenity.","example_zh":"湖畔花園帶來令人舒心的寧靜。","original_meaning":"寧靜","original_example":"The lake was peaceful and full of serenity.","original_example_zh":"湖面寧靜祥和。"},{"source_id":3886,"word":"servitude","meaning":"奴役","example":"The historical novel described a family's struggle to escape servitude.","example_zh":"歷史小說描寫一個家庭擺脫奴役的奮鬥。","original_meaning":"奴役","original_example":"They lived in servitude.","original_example_zh":"他們過著受奴役的生活。"},{"source_id":3887,"word":"shareholder","meaning":"股東","example":"The shareholder attended the company's annual meeting.","example_zh":"那位股東參加公司的年度會議。","original_meaning":"股東","original_example":"The shareholder attended the meeting.","original_example_zh":"股東出席了會議。"},{"source_id":3888,"word":"shipment","meaning":"運送；一批貨物","example":"A shipment of new books arrived at the school library.","example_zh":"一批新書運抵學校圖書館。","original_meaning":"運送","original_example":"The shipment arrived on time.","original_example_zh":"貨物準時送達。"},{"source_id":3889,"word":"siege","meaning":"圍攻；圍城","example":"The museum model showed a city under siege behind closed gates.","example_zh":"博物館模型呈現城門緊閉、遭到圍城的城市。","original_meaning":"圍攻","original_example":"The company made a strategic shift to digital services.","original_example_zh":"該公司進行了向數位服務的戰略轉變。"},{"source_id":3890,"word":"signatory","meaning":"簽署者","example":"Each signatory kept a copy of the agreement.","example_zh":"每位簽署者都保留一份協議副本。","original_meaning":"簽署者","original_example":"The shield protected him from the attack.","original_example_zh":"盾牌保護他免受攻擊。"},{"source_id":3891,"word":"silicon","meaning":"矽","example":"The museum displayed a silicon wafer beside an enlarged chip model.","example_zh":"博物館在放大的晶片模型旁展示矽晶圓。","original_meaning":"矽","original_example":"The shipment of goods arrived earlier than expected.","original_example_zh":"貨物比預期更早送達。"},{"source_id":3892,"word":"slaughter","meaning":"屠殺","example":"The memorial recalled the slaughter of civilians during the war.","example_zh":"紀念館追念戰爭期間遭屠殺的平民。","original_meaning":"屠殺","original_example":"The sudden news gave everyone a shock.","original_example_zh":"這則突如其來的消息讓所有人都大吃一驚。"},{"source_id":3893,"word":"smog","meaning":"霧霾","example":"A layer of smog obscured the distant city skyline.","example_zh":"一層霧霾遮住遠方城市天際線。","original_meaning":"霧霾","original_example":"There is a shortage of skilled workers in this field.","original_example_zh":"這個領域缺乏熟練工人。"},{"source_id":3894,"word":"sobriety","meaning":"清醒；嚴肅莊重","example":"The occasion called for sobriety rather than playful jokes.","example_zh":"這個場合需要嚴肅莊重，不適合開玩笑。","original_meaning":"清醒","original_example":"She spoke with sincerity during her apology.","original_example_zh":"她在道歉時語氣真誠。"},{"source_id":3895,"word":"sociology","meaning":"社會學","example":"The sociology class examined how public spaces bring communities together.","example_zh":"社會學課探討公共空間如何凝聚社區。","original_meaning":"社會學","original_example":"This monument has great historical significance.","original_example_zh":"這座紀念碑具有重大的歷史意義。"},{"source_id":3896,"word":"solitude","meaning":"孤獨；獨處","example":"She enjoyed a moment of solitude beside the quiet pond.","example_zh":"她享受在寧靜池塘旁獨處的片刻。","original_meaning":"孤獨","original_example":"The army began to advance at dawn.","original_example_zh":"軍隊在黎明時分開始進軍。"},{"source_id":3897,"word":"specification","meaning":"規格","example":"The builder checked each specification before assembling the model house.","example_zh":"建造者組裝模型屋前先核對每項規格。","original_meaning":"規格","original_example":"We finally found a simple solution to the problem.","original_example_zh":"我們終於為這個問題找到了一個簡單的解決方案。"},{"source_id":3898,"word":"specimen","meaning":"樣本","example":"The geologist examined a specimen of volcanic rock.","example_zh":"地質學家檢查一塊火山岩樣本。","original_meaning":"樣本","original_example":"His speech was truly inspiring to the audience.","original_example_zh":"他的演說確實激勵了在場的聽眾。"},{"source_id":3899,"word":"spectacle","meaning":"壯觀景象","example":"The waterfall was a magnificent spectacle after the rain.","example_zh":"雨後瀑布呈現壯麗景象。","original_meaning":"壯觀","original_example":"Thousands of spectators filled the stadium.","original_example_zh":"數千名觀眾擠滿了體育場。"},{"source_id":3900,"word":"spectrum","meaning":"光譜","example":"The prism spread white light into a visible spectrum.","example_zh":"稜鏡把白光分散成可見光譜。","original_meaning":"光譜","original_example":"The company showed steady growth over five years.","original_example_zh":"該公司在過去五年中展現出穩健的成長。"},{"source_id":3901,"word":"splendor","meaning":"壯麗","example":"The palace garden glowed in the splendor of the morning light.","example_zh":"宮殿花園在晨光中綻放壯麗光彩。","original_meaning":"壯麗","original_example":"The storm caused severe damage to the village.","original_example_zh":"風暴對該村莊造成了嚴重破壞。"},{"source_id":3902,"word":"stalemate","meaning":"僵局","example":"The negotiations reached a stalemate when neither side would change its proposal.","example_zh":"雙方都不願修改提案，談判陷入僵局。","original_meaning":"僵局","original_example":"Their strategy helped them win the competition.","original_example_zh":"他們的策略幫助他們贏得比賽。"},{"source_id":3903,"word":"statute","meaning":"法規","example":"The new statute protected the town's historic buildings.","example_zh":"新法規保護城鎮的歷史建築。","original_meaning":"法規","original_example":"The old structure collapsed after the earthquake.","original_example_zh":"舊建築在地震後倒塌。"},{"source_id":3904,"word":"sterilize","meaning":"消毒；滅菌","example":"The technician used an autoclave to sterilize the laboratory instruments.","example_zh":"技術人員用高壓蒸氣滅菌器為實驗室器械滅菌。","original_meaning":"消毒","original_example":"The teacher noticed the student’s potential early.","original_example_zh":"老師很早就發現了學生的潛力。"},{"source_id":3905,"word":"stimulus","meaning":"刺激","example":"The bright light provided a stimulus that made the seedlings bend toward it.","example_zh":"明亮光線形成刺激，讓幼苗朝它彎曲。","original_meaning":"刺激","original_example":"This subject requires deep understanding.","original_example_zh":"這門學科需要深入理解。"},{"source_id":3906,"word":"stipulate","meaning":"規定","example":"The rules stipulate that every team must use the same amount of wood.","example_zh":"規則規定，每隊必須使用相同數量的木材。","original_meaning":"規定","original_example":"The survey revealed interesting results.","original_example_zh":"調查揭示了有趣的結果。"},{"source_id":3907,"word":"stockpile","meaning":"儲備","example":"The community kept a stockpile of blankets for emergencies.","example_zh":"社區儲備一批毛毯以備緊急需要。","original_meaning":"儲備","original_example":"The system crashed due to a configuration error.","original_example_zh":"系統因設定錯誤而當機。"},{"source_id":3908,"word":"stratification","meaning":"分層","example":"The cliff revealed the stratification of rock formed over many years.","example_zh":"岩壁顯示多年形成的岩石分層。","original_meaning":"分層","original_example":"The team collaborated effectively on the project.","original_example_zh":"團隊在專案上合作無間。"},{"source_id":3909,"word":"stricken","meaning":"受災的","example":"Volunteers brought supplies to the flood-stricken village.","example_zh":"志工把物資送到受洪水侵襲的村莊。","original_meaning":"受災的","original_example":"Modern technology is evolving faster than ever.","original_example_zh":"現代科技的發展速度比以往任何時候都快。"},{"source_id":3910,"word":"subdivision","meaning":"細分","example":"The diagram showed the subdivision of the large field into smaller plots.","example_zh":"圖表呈現大田地細分為小區塊的方式。","original_meaning":"細分","original_example":"The temperature dropped below zero overnight.","original_example_zh":"氣溫在一夜之間降至零度以下。"},{"source_id":3911,"word":"subjective","meaning":"主觀的","example":"Her review was subjective because it reflected her own taste in color.","example_zh":"她的評論是主觀的，反映個人對色彩的偏好。","original_meaning":"主觀的","original_example":"The theory explains how gravity works.","original_example_zh":"該理論解釋了重力如何運作。"},{"source_id":3912,"word":"submission","meaning":"提交","example":"The students prepared their model for submission to the competition.","example_zh":"學生準備提交模型參加比賽。","original_meaning":"提交","original_example":"Heavy traffic caused a delay in arrival.","original_example_zh":"交通擁堵導致抵達時間延遲。"},{"source_id":3913,"word":"subordination","meaning":"從屬","example":"The diagram showed the subordination of the small units to the central office.","example_zh":"圖表顯示小單位從屬於中央辦公室的關係。","original_meaning":"從屬","original_example":"Regular training improves performance significantly.","original_example_zh":"定期訓練能顯著提升表現。"},{"source_id":3914,"word":"subsidy","meaning":"補助金","example":"The school received a subsidy to install solar panels.","example_zh":"學校獲得補助金，得以安裝太陽能板。","original_meaning":"補助金","original_example":"The transaction was completed securely online.","original_example_zh":"這筆交易已透過線上安全完成。"},{"source_id":3915,"word":"substitution","meaning":"替代","example":"The substitution of a lighter material made the model easier to carry.","example_zh":"換用較輕的材料，讓模型更容易攜帶。","original_meaning":"替代","original_example":"This trend shows increasing demand for AI skills.","original_example_zh":"這項趨勢顯示對人工智慧技能的需求日益增加。"},{"source_id":3916,"word":"subtlety","meaning":"微妙；細微之處","example":"The subtlety of her expression made the portrait especially lifelike.","example_zh":"她表情的細微變化讓肖像格外生動。","original_meaning":"微妙","original_example":"The trial lasted several months in court.","original_example_zh":"這場審判在法庭上持續了數個月。"},{"source_id":3917,"word":"subversion","meaning":"顛覆","example":"The novel depicted a secret campaign of subversion against the fictional regime.","example_zh":"小說描繪顛覆虛構政權的祕密活動。","original_meaning":"顛覆","original_example":"The university offers various degree programs.","original_example_zh":"該大學提供各種學位課程。"},{"source_id":3918,"word":"successor","meaning":"繼任者","example":"The retiring curator introduced her successor to the museum staff.","example_zh":"退休策展人向博物館員工介紹繼任者。","original_meaning":"繼任者","original_example":"The user interface is intuitive and easy to navigate.","original_example_zh":"使用者介面直觀且易於操作。"},{"source_id":3919,"word":"suffrage","meaning":"選舉權","example":"The exhibition traced the campaign for women's suffrage.","example_zh":"展覽回顧爭取女性選舉權的運動。","original_meaning":"選舉權","original_example":"The value of the property has increased.","original_example_zh":"該物業的價值已上漲。"},{"source_id":3920,"word":"superintendent","meaning":"總監","example":"The superintendent inspected the school buildings with the principal.","example_zh":"總監與校長一起巡視校舍。","original_meaning":"總監","original_example":"The vehicle was damaged in the collision.","original_example_zh":"車輛在碰撞中受損。"},{"source_id":3921,"word":"superiority","meaning":"優越","example":"The new design's superiority became clear during the weight test.","example_zh":"負重測試時，新設計的優越之處清楚顯現。","original_meaning":"優越","original_example":"The latest version includes bug fixes.","original_example_zh":"最新版本包含錯誤修正。"},{"source_id":3922,"word":"supplement","meaning":"補充品；補充教材","example":"The workbook served as a useful supplement to the main textbook.","example_zh":"練習冊是主要課本的實用補充教材。","original_meaning":"補充品","original_example":"The village lies beside a quiet river.","original_example_zh":"村莊坐落於一條寧靜的河流旁。"},{"source_id":3923,"word":"supremacy","meaning":"至高地位；霸權","example":"The team hoped to end its rival's supremacy in the annual chess tournament.","example_zh":"球隊希望終結對手在年度西洋棋賽的霸主地位。","original_meaning":"至高","original_example":"The virus spreads rapidly in crowded areas.","original_example_zh":"病毒在擁擠的區域迅速傳播。"},{"source_id":3924,"word":"surcharge","meaning":"附加費","example":"The hotel added a surcharge for the extra bed.","example_zh":"旅館為加床收取附加費。","original_meaning":"附加費","original_example":"The volume of traffic has doubled.","original_example_zh":"交通流量增加了一倍。"},{"source_id":3925,"word":"sustainability","meaning":"永續","example":"The project focused on sustainability by reusing materials and saving water.","example_zh":"專案透過再利用材料與節水，聚焦永續發展。","original_meaning":"永續","original_example":"The weather changed suddenly in the afternoon.","original_example_zh":"下午天氣突然轉變。"},{"source_id":3926,"word":"symbolism","meaning":"象徵主義；象徵手法","example":"The poem's symbolism linked the open window with freedom.","example_zh":"詩中的象徵手法把敞開的窗與自由連結。","original_meaning":"象徵主義","original_example":"This website provides useful tutorials.","original_example_zh":"這個網站提供實用的教學指南。"},{"source_id":3927,"word":"symposium","meaning":"研討會","example":"The university hosted a symposium on protecting local rivers.","example_zh":"大學舉辦保護當地河川的研討會。","original_meaning":"研討會","original_example":"The worker completed his task efficiently.","original_example_zh":"該名工人高效地完成了任務。"},{"source_id":3928,"word":"syndrome","meaning":"症候群","example":"The medical students studied a syndrome defined by a particular group of signs and symptoms.","example_zh":"醫學生研讀一種由特定徵象與症狀組合界定的症候群。","original_meaning":"症候群","original_example":"The world is becoming more interconnected.","original_example_zh":"世界正變得越來越互聯。"},{"source_id":3929,"word":"synthesis","meaning":"合成；綜合","example":"Her report offered a synthesis of ideas from several experiments.","example_zh":"她的報告綜合數個實驗的想法。","original_meaning":"合成","original_example":"The writer published a bestselling novel.","original_example_zh":"該作家出版了一部暢銷小說。"},{"source_id":3930,"word":"systematic","meaning":"系統的；有條理的","example":"The librarian used a systematic approach to sort the donated books.","example_zh":"圖書館員以有系統的方法分類捐贈書籍。","original_meaning":"系統的","original_example":"The year ended with strong economic growth.","original_example_zh":"該年以強勁的經濟增長作結。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-rebellion-01-v1","level":"senior","word":"rebellion","sort_order":1,"sense":"叛亂","alt_zh":"高中生在博物館觀看虛構歷史模型，成年居民集會反對不公統治，無戰鬥武器。","example":"The exhibit traced the causes of a rebellion against the unfair ruler.","example_zh":"展覽追溯反抗不公統治者的叛亂起因。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/rebellion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-recitation-01-v1","level":"senior","word":"recitation","sort_order":1,"sense":"朗誦","alt_zh":"高中女生在禮堂小舞臺上專注朗誦，同學安靜聆聽。","example":"Her recitation of the poem held the audience's attention.","example_zh":"她的詩歌朗誦吸引全場注意。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/recitation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reconnaissance-01-v1","level":"senior","word":"reconnaissance","sort_order":1,"sense":"偵察","alt_zh":"成年救援隊在安全高地操作無人機查看遠方淹水道路，無傷者或軍事情境。","example":"The rescue team used a drone for reconnaissance after the flood.","example_zh":"洪水過後，救援隊用無人機偵察環境。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reconnaissance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reconstruction-01-v1","level":"senior","word":"reconstruction","sort_order":1,"sense":"重建","alt_zh":"成年工程師與工人在安全工地修建連接兩村的橋，居民從遠處觀看。","example":"The reconstruction of the old bridge brought the villages together.","example_zh":"重建老橋讓兩個村莊重新連結。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reconstruction-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-referendum-01-v1","level":"senior","word":"referendum","sort_order":1,"sense":"公投","alt_zh":"成年居民在社區投票所投票，桌上擺著公園規劃模型，無文字。","example":"The town held a referendum on the proposed public park.","example_zh":"城鎮就公共公園提案舉行公投。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/referendum-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reformer-01-v1","level":"senior","word":"reformer","sort_order":1,"sense":"改革者","alt_zh":"成年教育工作者向社區代表展示有坡道、圖書室與開放教室的學校模型。","example":"The educational reformer argued for more accessible schools.","example_zh":"教育改革者主張讓學校更方便所有人就讀。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reformer-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-rehabilitation-01-v1","level":"senior","word":"rehabilitation","sort_order":1,"sense":"復健","alt_zh":"成年物理治療師在專業復健室陪成年病人使用扶手練習穩定步行，無傷口。","example":"The therapist guided his rehabilitation after the knee injury.","example_zh":"膝蓋受傷後，治療師指導他進行復健。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/rehabilitation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reiterate-01-v1","level":"senior","word":"reiterate","sort_order":1,"sense":"重申","alt_zh":"成年教練在球場旁向高中運動隊再次示意護具與安全界線。","example":"The coach will reiterate the safety rules before every practice.","example_zh":"每次練習前，教練都會重申安全規則。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reiterate-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reliance-01-v1","level":"senior","word":"reliance","sort_order":1,"sense":"依賴","alt_zh":"高中生在校園飲水補充站裝滿自己的水壺，旁邊只剩少量空瓶回收。","example":"The school reduced its reliance on bottled water by adding refill stations.","example_zh":"學校增設飲水補充站，減少對瓶裝水的依賴。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reliance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-remnant-01-v1","level":"senior","word":"remnant","sort_order":1,"sense":"殘餘","alt_zh":"花園邊保留一小段斑駁石牆，高中生在老師陪同下觀察。","example":"A remnant of the old wall stood beside the new garden.","example_zh":"新花園旁仍矗立一小段舊牆殘跡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/remnant-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-remuneration-01-v1","level":"senior","word":"remuneration","sort_order":1,"sense":"報酬","alt_zh":"成年演奏者在音樂廳後臺從主辦人手中接過報酬信封，氣氛友善。","example":"The musicians received fair remuneration for their performance.","example_zh":"音樂家為演出獲得合理報酬。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/remuneration-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-rendition-01-v1","level":"senior","word":"rendition","sort_order":1,"sense":"演繹","alt_zh":"高中合奏團在小音樂廳充滿活力地演奏，觀眾專心聆聽。","example":"The ensemble gave a lively rendition of the old folk tune.","example_zh":"合奏團生動演繹那首古老民謠。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/rendition-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-renovation-01-v1","level":"senior","word":"renovation","sort_order":1,"sense":"翻新","alt_zh":"修繕後明亮圖書館有整齊書架、新窗與舒適座位，高中生開心使用。","example":"The renovation gave the library brighter study rooms.","example_zh":"翻新工程讓圖書館有了更明亮的自習室。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/renovation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reparation-01-v1","level":"senior","word":"reparation","sort_order":1,"sense":"賠償","alt_zh":"成年施工公司代表交付修復花園的費用文件，園丁在背景補植樹木。","example":"The agreement included reparation for the damage to the shared garden.","example_zh":"協議包含對公共花園損壞的賠償。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reparation-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-repercussion-01-v1","level":"senior","word":"repercussion","sort_order":1,"sense":"影響","alt_zh":"道路遠端封閉，村莊市集有空攤位與較少顧客，成年攤商擔憂查看。","example":"The road closure had an unexpected repercussion for the village market.","example_zh":"道路封閉對村莊市集造成意外影響。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/repercussion-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-repository-01-v1","level":"senior","word":"repository","sort_order":1,"sense":"儲存庫","alt_zh":"成年檔案員在整齊資料櫃保存老照片，高中訪客安靜參觀。","example":"The archive became a repository for the town's historic photographs.","example_zh":"檔案館成為保存城鎮歷史照片的資料庫。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/repository-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-repression-01-v1","level":"senior","word":"repression","sort_order":1,"sense":"壓迫","alt_zh":"博物館歷史模型呈現虛構成年官員阻止和平市民進入會議廳，無武器傷害或標語。","example":"The exhibit examined the repression of peaceful dissent.","example_zh":"展覽探討對和平異議的壓制。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/repression-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-reproduction-01-v1","level":"senior","word":"reproduction","sort_order":1,"sense":"繁殖","alt_zh":"老師在高中教室展示花、花粉、種子與幼苗的教學模型。","example":"The biology lesson explored reproduction in flowering plants.","example_zh":"生物課探討開花植物的繁殖。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/reproduction-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-republic-01-v1","level":"senior","word":"republic","sort_order":1,"sense":"共和國","alt_zh":"高中生在公民教室觀察成年公民投票與代表議會的立體模型，無真實政黨。","example":"The class studied how citizens elect representatives in a republic.","example_zh":"班上研究共和國中的公民如何選出代表。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/republic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-requisite-01-v1","level":"senior","word":"requisite","sort_order":1,"sense":"必要的","alt_zh":"高中生與老師在工坊整齊準備修理木椅所需的工具與護具。","example":"The team gathered the requisite tools before repairing the benches.","example_zh":"團隊修理長椅前先備齊必要工具。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/requisite-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-resemblance-01-v1","level":"senior","word":"resemblance","sort_order":1,"sense":"相似","alt_zh":"高中生在自然館比較一隻竹節葉蟲與旁邊綠葉，外形清楚相似。","example":"The resemblance between the leaf and the insect was remarkable.","example_zh":"那片葉子與昆蟲的相似程度令人驚訝。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/resemblance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-resentment-01-v1","level":"senior","word":"resentment","sort_order":1,"sense":"怨恨","alt_zh":"高中女生原本抱臂不悅，同學誠懇邀她加入圓桌活動，她的神情開始緩和。","example":"Her resentment faded after the group apologized for leaving her out.","example_zh":"小組為漏邀她道歉後，她的怨懟逐漸消退。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/resentment-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-residue-01-v1","level":"senior","word":"residue","sort_order":1,"sense":"殘留物","alt_zh":"高中生在老師旁觀察透明玻璃杯底少量乾燥白色礦物殘留。","example":"A chalky residue remained in the cup after the water evaporated.","example_zh":"水蒸發後，杯中留下白堊狀殘留物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/residue-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-resilience-01-v1","level":"senior","word":"resilience","sort_order":1,"sense":"韌性","alt_zh":"成年居民與高中志工在風暴後合作扶正樹苗、修復花園，無傷者。","example":"The community showed resilience by rebuilding the garden after the storm.","example_zh":"社區在風暴後重建花園，展現韌性。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/resilience-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-resolution-01-v1","level":"senior","word":"resolution","sort_order":1,"sense":"決議","alt_zh":"成年市議員有序舉手表決，桌上有古樹與公園模型。","example":"The council passed a resolution to protect the old trees.","example_zh":"議會通過保護老樹的決議。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/resolution-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-resonance-01-v1","level":"senior","word":"resonance","sort_order":1,"sense":"共鳴","alt_zh":"音樂老師向高中生示範輕撥木吉他琴弦，同學專注聆聽。","example":"The guitar's wooden body strengthened the resonance of its strings.","example_zh":"吉他的木製琴身增強琴弦的共鳴。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/resonance-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-restitution-01-v1","level":"senior","word":"restitution","sort_order":1,"sense":"歸還","alt_zh":"成年博物館員戴手套，莊重將古陶器交還社群代表，雙方尊重友好。","example":"The museum arranged the restitution of the artifact to its original community.","example_zh":"博物館安排把文物歸還原屬社群。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/restitution-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":